using UnityEngine;
using UnityEngine.SceneManagement;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            var s = SceneManager.GetSceneByName("CampusTerrain");
            foreach (var root in s.GetRootGameObjects())
            {
                result.Log(root.name);
                foreach (Transform child in root.transform)
                {
                    result.Log("  " + child.name);
                    foreach (Transform nested in child)
                        if (nested.childCount > 5)
                            result.Log("    " + nested.name + " children=" + nested.childCount);
                }
            }

            foreach (var r in Object.FindObjectsByType<CampusDriveTelemetry>(FindObjectsSortMode.None))
                r.Close();
        }
    }
}
